from math import gcd

def solve(M, x):
	if M == 1:
		return [i + 1 for i in range(x)]
	ans = [1]
	for n in range(2, x + 1):
		if n >= M:
			ans.append(ans[-1])
		elif M % n != 0 and M % n <= ans[-1]:
			ans.append(ans[-1] + 1)
		else:
			ans.append(ans[-1])
	print(*ans)
t = int(input())
for xyz in range(t):
	(M, x) = map(int, input().split())
	solve(M, x)
